const listInvoiceMatchCandidates = `-- name: ListInvoiceMatchCandidates :many
SELECT i.id, i.uuid, i.invoice_number, i.issue_date, i.payment_due_date, i.currency,
       i.customer_id, i.customer_name, i.customer_tax_number, i.customer_identity_number,
       COALESCE(c.bank_accounts, '[]'::jsonb) AS bank_accounts,
       (CASE WHEN i.currency = $1::text THEN i.payable_amount ELSE i.payable_amount_try END)::numeric AS comparable_amount,
       COALESCE((SELECT sum(m.amount) FROM bank_transaction_matches m
                 WHERE m.taxpayer_id = i.taxpayer_id AND m.target_type = 'invoice' AND m.target_id = i.id), 0)::numeric AS matched_amount
FROM invoices i
LEFT JOIN customers c ON c.taxpayer_id = i.taxpayer_id AND c.id = i.customer_id
WHERE i.taxpayer_id = $2
  AND i.direction = $3
  AND i.status_normalized = 'active'
  AND i.issue_date BETWEEN $4 AND $5
  AND (i.currency = $1::text OR ($1::text = 'TRY' AND i.payable_amount_try IS NOT NULL))
  AND (
        abs((CASE WHEN i.currency = $1::text THEN i.payable_amount ELSE i.payable_amount_try END) - $6::numeric) <= $7::numeric
     OR ($8::text IS NOT NULL AND i.customer_tax_number = $8::text)
     OR ($9::text IS NOT NULL AND i.customer_identity_number = $9::text)
     OR i.invoice_number = ANY($10::text[])
     OR ($11::text IS NOT NULL AND c.bank_accounts @> jsonb_build_array(jsonb_build_object('iban', $11::text)))
  )
ORDER BY i.issue_date DESC, i.id
LIMIT 200
`

